require __DIR__.'/includes/bootstrap.php';if(empty($_SESSION['user_id']))redirect('/login.php');$s=$pdo->prepare('SELECT email FROM users WHERE id=?');$s->execute([$_SESSION['user_id']]);$u=$s->fetch();$s=$pdo->prepare('SELECT id,total,status,created_at FROM orders WHERE user_id=? ORDER BY id DESC');$s->execute([$_SESSION['user_id']]);$orders=$s->fetchAll();$pageTitle='Account';require __DIR__.'/includes/header.php';?><h1>My Account</h1><?php if(isset($_GET['ordered'])):?><p class="success">Demo order created successfully.</p><?php endif;?><p>Signed in as <strong><?=e($u['email'])?></strong></p><h2>Orders</h2><?php if(!$orders):?><p>No orders yet.</p><?php else:?><table><tr><th>Order</th><th>Status</th><th>Total</th><th>Date</th></tr><?php foreach($orders as $o):?><tr><td>#<?=(int)$o['id']?></td><td><?=e($o['status'])?></td><td>$<?=number_format((float)$o['total'],2)?></td><td><?=e($o['created_at'])?></td></tr><?php endforeach;?></table><?php endif;?><?php require __DIR__.'/includes/footer.php';?>
